mapper.update:
update qms_change set m4_types = #{f.m4Types, typeHandler=org.apache.ibatis.type.ArrayTypeHandler}::varchar(10)[],
                      before_desc = #{f.beforeDesc}, after_desc = #{f.afterDesc}, reason_desc = #{f.reasonDesc},
                      impact_desc = #{f.impactDesc}, revert_cond = #{f.revertCond},
                      row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where eco_id = #{ecoId} and row_ver = #{f.rowVer}
